            {/* Tooltip za prikaz naziva i vrednosti */}
            {hoveredDistrict && (
                <div style={{
                    position: 'fixed', // Fixed je bolji jer prati miša preko celog ekrana
                    top: mousePos.y + 15, // Pomereno malo ispod miša da ga prst/kursor ne bi prekrio
                    left: mousePos.x + 15,
                    backgroundColor: 'rgba(255, 255, 255, 0.95)',
                    border: '1px solid #e2e8f0',
                    boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
                    padding: '6px 12px',
                    borderRadius: '6px',
                    pointerEvents: 'none', // SPREČAVA treperenje tooltipa kad pređeš mišem preko njega
                    zIndex: 9999,
                    fontSize: '13px',
                    color: '#1e293b',
                    whiteSpace: 'nowrap'
                }}>
                    <strong style={{ display: 'block', marginBottom: '2px' }}>{hoveredDistrict}</strong>
                    {/* Ako postoji vrednost, prikazujemo je ispod */}
                    {values && values[hoveredDistrict] ? (
                        <span style={{ color: '#64748b', fontSize: '12px' }}>Вредност: {values[hoveredDistrict]}</span>
                    ) : (
                        <span style={{ color: '#94a3b8', fontSize: '11px', fontStyle: 'italic' }}>Нема података</span>
                    )}
                </div>
            )}

